INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(3250, 'wide', 'waɪd', 'adjective', '{"zh-TW":["寬廣的；廣泛的","大量的"],"en":["covering a large area or range","extensive"]}', NULL, 'wide range/wide variety', '[{"en":"We offer a wide range of products.","zh-TW":"我們提供廣泛的產品系列。"}]', '{"noun":"width","adverb":"widely"}', NULL, 1, 3250, NULL),
(3251, 'widen', '/ˈwaɪdn/', 'verb', '{"zh-TW":["加寬；擴大"],"en":["to make or become wider or more extensive"]}', NULL, 'widen the gap / widen the scope / widen access', '[{"en":"The gap between rich and poor continues to widen.","zh-TW":"貧富差距持續擴大。"},{"en":"We plan to widen the scope of our services.","zh-TW":"我們計劃擴大服務範圍。"}]', '{"noun":"width","verb":"widen","adjective":"wide"}', NULL, 2, 3251, NULL),
(3252, 'widespread', '/ˈwaɪdspred/', 'adjective', '{"zh-TW":["普遍的；廣泛的"],"en":["found or distributed over a large area"]}', NULL, 'widespread use / widespread concern / widespread adoption', '[{"en":"There is widespread concern about data privacy.","zh-TW":"人們普遍關注資料隱私問題。"},{"en":"The technology has gained widespread adoption.","zh-TW":"這項技術已被廣泛採用。"}]', '{"adjective":"widespread"}', NULL, 4, 3252, NULL),
(3253, 'wildfire', '/ˈwaɪldfaɪər/', 'noun', '{"zh-TW":["野火；山火"],"en":["an uncontrolled fire spreading rapidly through vegetation"]}', NULL, 'contain a wildfire / wildfire risk', '[{"en":"The wildfire destroyed thousands of acres of forest.","zh-TW":"野火摧毀了數千英畝的森林。"},{"en":"Climate change increases the frequency and intensity of wildfires.","zh-TW":"氣候變遷增加了野火的頻率和強度。"}]', NULL, NULL, 3, 3253, NULL),
(3254, 'willing', '/ˈwɪlɪŋ/', 'adjective', '{"zh-TW":["願意的；樂意的"],"en":["ready or eager to do something"]}', NULL, 'willing to / willing participant / willing and able', '[{"en":"Are you willing to relocate for the job?","zh-TW":"你願意為這份工作搬遷嗎？"},{"en":"We need willing participants for the pilot program.","zh-TW":"我們需要願意參加試驗計畫的人。"}]', '{"noun":"willingness","adjective":"willing, unwilling","adverb":"willingly"}', NULL, 3, 3254, NULL),
(3255, 'wind', '/wɪnd/', 'noun', '{"zh-TW":["風"],"en":["moving air"]}', '{"root":{"text":"wind","meaning":"blow (吹)"},"logic":"空氣的流動。"}', 'strong wind / wind speed / wind power', '[{"en":"The wind blew the leaves off the trees.","zh-TW":"風把樹葉從樹上吹落。"},{"en":"Wind power is a renewable energy source.","zh-TW":"風力是一種再生能源。"}]', '{"adjective":"windy"}', NULL, 1, 3255, NULL),
(3256, 'wireless', '/ˈwaɪərlɪs/', 'adjective', '{"zh-TW":["無線的"],"en":["using radio signals instead of wires"]}', NULL, 'wireless network / wireless charging', '[{"en":"The hotel has free wireless internet.","zh-TW":"飯店有免費無線網路。"},{"en":"This phone supports wireless charging.","zh-TW":"這支手機支援無線充電。"}]', NULL, NULL, 3, 3256, NULL),
(3257, 'withdraw', '/wɪðˈdrɔː/', 'verb', '{"zh-TW":["撤回；提款","退出"],"en":["to take back; to remove money from a bank","to leave or pull out"]}', NULL, 'withdraw funds / withdraw from / withdraw support', '[{"en":"The investor withdrew funding from the project.","zh-TW":"投資者從專案中撤回了資金。"},{"en":"She withdrew her application for the position.","zh-TW":"她撤回了該職位的申請。"}]', '{"noun":"withdrawal","verb":"withdraw"}', NULL, 3, 3257, NULL),
(3258, 'withdrawal', 'wɪðˈdrɔːəl', 'noun', '{"zh-TW":["撤回；提款","退出"],"en":["the act of taking back","removing money from an account"]}', NULL, 'cash withdrawal/contract withdrawal', '[{"en":"Please process the withdrawal request.","zh-TW":"請處理提款申請。"}]', '{"verb":"withdraw","adjective":"withdrawn"}', NULL, 4, 3258, 487),
(3259, 'withhold', '/wɪðˈhoʊld/', 'verb', '{"zh-TW":["扣留；隱瞞"],"en":["to hold back; to refrain from giving"]}', NULL, 'withhold information / withhold payment / withhold tax', '[{"en":"The company withheld the bonus due to poor performance.","zh-TW":"公司因業績不佳而扣留了獎金。"},{"en":"Employers must withhold income tax from wages.","zh-TW":"雇主必須從薪資中預扣所得稅。"}]', '{"noun":"withholding","verb":"withhold"}', NULL, 3, 3259, NULL),
(3260, 'withstand', '/wɪðˈstænd/', 'verb', '{"zh-TW":["承受；抵抗"],"en":["to remain undamaged by; to resist"]}', NULL, 'withstand pressure / withstand competition / withstand scrutiny', '[{"en":"The company withstood intense market competition.","zh-TW":"公司經受住了激烈的市場競爭。"},{"en":"The product is designed to withstand extreme conditions.","zh-TW":"該產品設計為可承受極端條件。"}]', '{"verb":"withstand"}', NULL, 3, 3260, NULL),
(3261, 'witness', '/ˈwɪtnəs/', 'noun, verb', '{"zh-TW":["目擊者；證人","目睹；見證"],"en":["a person who sees an event","to see something happen"]}', NULL, 'witness growth / bear witness / expert witness', '[{"en":"The industry witnessed rapid growth last year.","zh-TW":"該行業去年見證了快速增長。"},{"en":"We are witnessing a major shift in consumer behavior.","zh-TW":"我們正在見證消費者行為的重大轉變。"}]', '{"noun":"witness","verb":"witness"}', NULL, 3, 3261, NULL),
(3262, 'work', 'wɜːrk', 'verb', '{"zh-TW":["工作；運作","有效"],"en":["to do a job","to function correctly"]}', NULL, 'work on/together/remotely', '[{"en":"The team works remotely on Fridays.","zh-TW":"團隊週五遠程工作。"}]', '{"noun":"work, worker","adjective":"working","adverb":"workably"}', NULL, 1, 3262, NULL),
(3263, 'workflow', '/ˈwɜːrkfloʊ/', 'noun', '{"zh-TW":["工作流程"],"en":["the sequence of steps in a business process"]}', NULL, 'optimize workflow / workflow management / automate workflow', '[{"en":"Automating the workflow saved hours of manual work each week.","zh-TW":"自動化工作流程每週節省了數小時的手動工作。"},{"en":"The new software streamlined our approval workflow.","zh-TW":"新軟體簡化了我們的審批工作流程。"}]', '{"verb":"workflow"}', NULL, 3, 3263, 949),
(3264, 'workforce', '/ˈwɜːrkfɔːrs/', 'noun', '{"zh-TW":["勞動力；員工總數"],"en":["the people engaged in work"]}', NULL, 'skilled workforce / workforce development / reduce the workforce', '[{"en":"The company has a workforce of 5,000 employees.","zh-TW":"公司擁有5000名員工。"},{"en":"Investing in workforce development is essential.","zh-TW":"投資勞動力發展至關重要。"}]', '{"noun":"workforce, work, worker"}', NULL, 3, 3264, NULL),
(3265, 'workload', '/ˈwɜːrkloʊd/', 'noun', '{"zh-TW":["工作量；工作負擔"],"en":["the amount of work assigned to or done by an employee or team"]}', NULL, 'manage workload / heavy workload / workload balance / workload distribution', '[{"en":"The new hire helped reduce the team''s heavy workload.","zh-TW":"新員工幫助減輕了團隊沉重的工作量。"},{"en":"Workload distribution must be fair to prevent employee burnout.","zh-TW":"工作量分配必須公平以防止員工倦怠。"}]', '{"adjective":"workload-intensive"}', NULL, 3, 3265, 488),
(3266, 'workplace', 'ˈwɜːrkpleɪs', 'noun', '{"zh-TW":["工作場所；職場","辦公場所"],"en":["where people work","an office or factory"]}', NULL, 'safe workplace/workplace culture', '[{"en":"Maintaining a safe workplace is essential.","zh-TW":"維持安全的工作場所至關重要。"}]', '{"adjective":"workplace-based"}', NULL, 3, 3266, 243),
(3267, 'workshop', '/ˈwɜːrkʃɑːp/', 'noun', '{"zh-TW":["研討會；工作坊"],"en":["a meeting for discussion or practical work"]}', NULL, 'training workshop / conduct a workshop / hands-on workshop', '[{"en":"The HR department organized a leadership workshop.","zh-TW":"人資部門組織了一場領導力工作坊。"},{"en":"The workshop covered project management skills.","zh-TW":"工作坊涵蓋了專案管理技能。"}]', '{"noun":"workshop"}', NULL, 3, 3267, NULL),
(3268, 'world', 'wɜːrld', 'noun', '{"zh-TW":["世界；全球","領域"],"en":["the Earth and its people","a particular field"]}', NULL, 'global world/world market', '[{"en":"We operate in a competitive world market.","zh-TW":"我們在競爭激烈的全球市場中運營。"}]', '{"adjective":"worldwide, worldly","adverb":"worldwide"}', NULL, 2, 3268, NULL),
(3269, 'worldwide', 'ˈwɜːrldwaɪd', 'adjective', '{"zh-TW":["全球的；世界性的","世界範圍的"],"en":["extending throughout the world","international"]}', NULL, 'worldwide distribution/worldwide recognition', '[{"en":"Our products have worldwide distribution.","zh-TW":"我們的產品在全球分銷。"}]', '{"adverb":"worldwide"}', NULL, 3, 3269, 489),
(3270, 'worth', '/wɜːrθ/', 'noun, adjective', '{"zh-TW":["價值","值得的"],"en":["the value of something","deserving of"]}', NULL, 'worth mentioning / net worth / worth the effort', '[{"en":"The investment is definitely worth the risk.","zh-TW":"這項投資絕對值得冒險。"},{"en":"The company''s net worth exceeded $1 billion.","zh-TW":"公司淨值超過了10億美元。"}]', '{"noun":"worth","adjective":"worth, worthy, worthwhile"}', NULL, 2, 3270, NULL),
(3271, 'worthwhile', '/ˌwɜːrθˈwaɪl/', 'adjective', '{"zh-TW":["值得的；有價值的"],"en":["worth the time, money, or effort spent"]}', NULL, 'worthwhile investment / worthwhile endeavor / make it worthwhile', '[{"en":"The training program proved to be a worthwhile investment.","zh-TW":"培訓計畫被證明是一項值得的投資。"},{"en":"It''s worthwhile to compare prices before purchasing.","zh-TW":"購買前比較價格是值得的。"}]', '{"adjective":"worthwhile, worthy","noun":"worth"}', NULL, 4, 3271, NULL),
(3272, 'worthy', '/ˈwɜːrði/', 'adjective', '{"zh-TW":["值得的；有價值的"],"en":["deserving respect or attention"]}', NULL, 'worthy of / worthy cause / noteworthy', '[{"en":"The proposal is worthy of consideration.","zh-TW":"這個提案值得考慮。"},{"en":"They donated to a worthy cause.","zh-TW":"他們為一項有價值的事業捐款。"}]', '{"noun":"worth, worthiness","adjective":"worthy, unworthy, noteworthy"}', NULL, 2, 3272, NULL),
(3273, 'wrap', '/ræp/', 'noun', '{"zh-TW":["捲餅；包裹"],"en":["food wrapped in a flatbread or tortilla"]}', NULL, 'chicken wrap / veggie wrap', '[{"en":"She ordered a chicken wrap with a side salad.","zh-TW":"她點了一個雞肉捲餅配沙拉。"},{"en":"Wraps are a popular choice for a quick lunch.","zh-TW":"捲餅是快速午餐的熱門選擇。"}]', NULL, NULL, 1, 3273, NULL),
(3274, 'write', 'raɪt', 'verb', '{"zh-TW":["書寫；撰寫","寫作"],"en":["to form letters or words","to compose"]}', NULL, 'write a report/email', '[{"en":"Please write a summary of the meeting.","zh-TW":"請撰寫會議摘要。"}]', '{"noun":"writing, writer","adjective":"written","adverb":"writely"}', NULL, 2, 3274, NULL),
(3275, 'write-down', '/ˈraɪt daʊn/', 'noun', '{"zh-TW":["資產減記"],"en":["a partial reduction in the book value of an asset that has decreased in value"]}', NULL, 'record a write-down / write-down of inventory', '[{"en":"A write-down of inventory was required after damaged goods were discovered.","zh-TW":"發現受損貨物後需要對庫存進行資產減記。"},{"en":"The write-down reduced the asset''s book value by 40%.","zh-TW":"資產減記將資產的帳面價值降低了40%。"}]', '{"verb":"write down"}', NULL, 4, 3275, NULL),
(3276, 'write-off', '/ˈraɪt ɒf/', 'noun', '{"zh-TW":["核銷；沖銷"],"en":["the removal of an uncollectable asset from the books"]}', NULL, 'write off a debt / tax write-off / bad debt write-off', '[{"en":"The company wrote off $5 million in uncollectable receivables.","zh-TW":"公司沖銷了500萬美元的無法收回應收帳款。"},{"en":"A write-off reduced taxable income for the year.","zh-TW":"核銷減少了當年的應稅收入。"}]', '{"verb":"write off"}', NULL, 3, 3276, NULL),
(3277, 'write-up', '/ˈraɪtʌp/', 'noun', '{"zh-TW":["書面報告；評論"],"en":["a written account or review of something"]}', NULL, 'prepare a write-up / formal write-up', '[{"en":"The journalist prepared a write-up of the product launch.","zh-TW":"記者準備了產品發布的書面報告。"},{"en":"Please submit a write-up of your project findings.","zh-TW":"請提交您的項目發現的書面報告。"}]', '{"verb":"write up"}', NULL, 3, 3277, NULL),
(3278, 'written', 'ˈrɪtən', 'adjective', '{"zh-TW":["書面的；成文的","文字的"],"en":["expressed in writing","documented"]}', NULL, 'written agreement/written confirmation', '[{"en":"Please provide written confirmation.","zh-TW":"請提供書面確認。"}]', '{"verb":"write","adverb":"in writing"}', NULL, 3, 3278, NULL),
(3279, 'wrong', 'rɒŋ', 'adjective', '{"zh-TW":["錯誤的；不對的","不適當的"],"en":["not correct","morally bad"]}', NULL, 'wrong decision/go wrong', '[{"en":"We made the wrong decision initially.","zh-TW":"我們最初做出了錯誤的決定。"}]', '{"adverb":"wrongly"}', NULL, 2, 3279, NULL),
(3280, 'X-ray', '/ˈɛks reɪ/', 'noun', '{"zh-TW":["X光；X射線"],"en":["a type of electromagnetic radiation used for imaging"]}', NULL, 'take an X-ray / chest X-ray', '[{"en":"The doctor ordered a chest X-ray to check for pneumonia.","zh-TW":"醫生要求胸部X光以檢查肺炎。"},{"en":"The X-ray showed no broken bones.","zh-TW":"X光顯示沒有骨折。"}]', '{"verb":"X-ray","adjective":"X-rayed"}', NULL, 2, 3280, NULL),
(3281, 'year', 'jɪr', 'noun', '{"zh-TW":["年；年份","一整年"],"en":["a period of 12 months","a specific calendar year"]}', NULL, 'fiscal year/last year', '[{"en":"The annual report covers the last fiscal year.","zh-TW":"年度報告涵蓋了最後一個財政年度。"}]', '{"adjective":"yearly, annual","adverb":"yearly, annually"}', NULL, 1, 3281, NULL),
(3282, 'year-over-year', '/ˌjɪər ˈoʊvər jɪər/', 'adjective', '{"zh-TW":["同比的；年比年的"],"en":["comparing a statistic for one period to the same period in the prior year"]}', NULL, 'year-over-year growth / year-over-year comparison', '[{"en":"The company reported a 20% year-over-year increase in revenue.","zh-TW":"公司報告了20%的同比收入增長。"},{"en":"Year-over-year performance metrics help remove seasonal distortions.","zh-TW":"同比績效指標有助於消除季節性扭曲。"}]', '{"abbreviation":"YoY"}', NULL, 5, 3282, NULL),
(3283, 'yield', '/jiːld/', 'verb, noun', '{"zh-TW":["【主要意義-動詞/名詞】讓步；屈服","【次要意義-名詞】產量；收益率","【次要意義-動詞】產出；獲得（利潤/成果）","【次要意義-動詞（交通）】讓行；讓路"],"en":["[primary] to give way; to surrender","[secondary - noun] the amount of something produced; financial return","[secondary - verb] to produce a result, crop, or profit","[secondary - verb] to give way to traffic"]}', NULL, 'crop yield / bond yield / yield to pressure / yield results', '[{"en":"The investment yielded a 12 percent annual return.","zh-TW":"這筆投資每年產生12%的回報。"},{"en":"The new farmland is expected to yield three harvests per year.","zh-TW":"新農地預計每年可收穫三次。"},{"en":"Government bonds currently yield around 4 percent.","zh-TW":"政府債券目前的收益率約為4%。"}]', '{"adjective":"high-yielding"}', 'yield 作名詞意為「產量/收益率」（bond yield = 債券殖利率），動詞意為「產出/獲得」，是 TOEIC 財務和農業文章的高頻詞彙，考生常誤以為只有「讓步」的意思。', 2, 3283, NULL),
(3284, 'zero-sum', '/ˈzɪəroʊ sʌm/', 'adjective', '{"zh-TW":["零和的"],"en":["describing a situation where one party''s gain is exactly balanced by another''s loss"]}', NULL, 'zero-sum negotiation / zero-sum game / zero-sum competition', '[{"en":"Trade wars are often described as zero-sum games with no winners.","zh-TW":"貿易戰通常被描述為沒有贏家的零和遊戲。"},{"en":"A win-win deal avoids the zero-sum dynamic and benefits both parties.","zh-TW":"雙贏的交易避免了零和動態並使雙方受益。"}]', NULL, NULL, 3, 3284, NULL),
(3285, 'zone', '/zoʊn/', 'noun', '{"zh-TW":["地帶；區域"],"en":["an area with particular characteristics"]}', NULL, 'time zone / free trade zone / comfort zone', '[{"en":"The factory is located in a free trade zone.","zh-TW":"工廠位於自由貿易區。"},{"en":"Employees should step out of their comfort zones.","zh-TW":"員工應該走出舒適圈。"}]', '{"noun":"zone, zoning","verb":"zone"}', NULL, 1, 3285, NULL),
(3286, 'zoning', '/ˈzəʊnɪŋ/', 'noun', '{"zh-TW":["分區；土地使用規劃"],"en":["the system of dividing land into zones for different uses"]}', NULL, 'zoning law / commercial zoning', '[{"en":"The land is zoned for mixed-use development.","zh-TW":"這片土地被劃定為混合用途開發區。"},{"en":"Zoning restrictions prevented the building of factories nearby.","zh-TW":"分區限制阻止了附近建造工廠。"}]', '{"verb":"zone","adjective":"zoned"}', NULL, 2, 3286, NULL);
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('account for', '解釋；佔（比例）', 'to explain or constitute a proportion', '[{"en":"Online sales account for 30% of total revenue.","zh-TW":"線上銷售佔總收入的30%。"},{"en":"How do you account for the discrepancy?","zh-TW":"你如何解釋這個差異？"},{"note":"也可表示「對…負責」。"}]', 'phrasal verb'),
('back up', '支持；備份', 'to support or make a copy of data', '[{"en":"Please back up all files before updating the system.","zh-TW":"請在更新系統前備份所有文件。"},{"en":"Can you back up your claim with evidence?","zh-TW":"你能用證據支持你的說法嗎？"},{"note":"名詞形式為 backup（備份）。"}]', 'phrasal verb'),
('break down', '分解；故障；崩潰', 'to divide into parts or stop functioning', '[{"en":"Let me break down the costs for you.","zh-TW":"讓我為你分解這些費用。"},{"en":"The machine broke down during production.","zh-TW":"機器在生產過程中故障了。"},{"note":"名詞 breakdown 指故障或明細表。"}]', 'phrasal verb'),
('bring about', '導致；引起', 'to cause something to happen', '[{"en":"The new policy brought about significant changes.","zh-TW":"新政策帶來了重大變化。"},{"en":"What brought about the merger?","zh-TW":"是什麼促成了合併？"},{"note":"較正式，可替換為 cause, lead to。"}]', 'phrasal verb'),
('bring up', '提出；養育', 'to mention or raise a topic', '[{"en":"She brought up an important issue at the meeting.","zh-TW":"她在會議上提出了一個重要問題。"},{"en":"I was brought up in a bilingual household.","zh-TW":"我在雙語家庭中長大。"},{"note":"在商務場合多指「提出議題」。"}]', 'phrasal verb'),
('call off', '取消', 'to cancel a planned event or activity', '[{"en":"They called off the conference due to the typhoon.","zh-TW":"他們因颱風取消了會議。"},{"en":"The strike was called off after negotiations.","zh-TW":"談判後罷工被取消了。"},{"note":"同義詞：cancel。"}]', 'phrasal verb'),
('carry out', '執行；實施；完成', 'to do or complete something, especially something planned', '[{"en":"The company carried out a customer satisfaction survey.","zh-TW":"公司進行了一項顧客滿意度調查。"},{"en":"We need to carry out the plan as scheduled.","zh-TW":"我們需要按計劃執行。"},{"note":"可替換為 conduct, execute, implement。"}]', 'phrasal verb'),
('catch up with', '趕上；跟上', 'to reach the same level or standard as someone', '[{"en":"We need to catch up with our competitors.","zh-TW":"我們需要趕上競爭對手。"},{"en":"I''ll catch up with you after the meeting.","zh-TW":"會議後我會跟你碰面。"},{"note":"也可表示「與…敘舊」。"}]', 'phrasal verb'),
('check in', '報到；登記入住', 'to register or report one''s arrival', '[{"en":"Guests can check in after 3 PM.","zh-TW":"客人可以在下午3點後辦理入住。"},{"en":"Please check in at the front desk upon arrival.","zh-TW":"請到達時在前台登記。"},{"note":"名詞 check-in 常用於飯店和機場。"}]', 'phrasal verb'),
('check out', '退房；查看', 'to leave a hotel or examine something', '[{"en":"We need to check out by noon.","zh-TW":"我們需要在中午前退房。"},{"en":"Check out the new product catalog.","zh-TW":"看看新的產品目錄。"},{"note":"口語中也表示「看看」。"}]', 'phrasal verb'),
('come across', '偶然遇到；給人印象', 'to find or meet by chance', '[{"en":"I came across an interesting article about AI.","zh-TW":"我偶然看到一篇關於AI的有趣文章。"},{"en":"She comes across as very professional.","zh-TW":"她給人非常專業的印象。"},{"note":"同義詞：run into, stumble upon。"}]', 'phrasal verb'),
('come up with', '想出；提出', 'to think of or produce an idea or solution', '[{"en":"The team came up with an innovative solution.","zh-TW":"團隊想出了一個創新的解決方案。"},{"en":"Can you come up with a better proposal?","zh-TW":"你能提出一個更好的提案嗎？"},{"note":"常用於腦力激盪和問題解決情境。"}]', 'phrasal verb'),
('count on', '依靠；指望', 'to rely or depend on someone or something', '[{"en":"You can always count on her to meet deadlines.","zh-TW":"你總是可以指望她在截止日期前完成。"},{"en":"We''re counting on your cooperation.","zh-TW":"我們指望您的合作。"},{"note":"同義詞：rely on, depend on。"}]', 'phrasal verb'),
('cut back on', '削減；縮減', 'to reduce the amount or level of something', '[{"en":"The company cut back on travel expenses.","zh-TW":"公司削減了差旅費用。"},{"en":"We need to cut back on unnecessary spending.","zh-TW":"我們需要削減不必要的開支。"},{"note":"也可用 cut down on。"}]', 'phrasal verb'),
('deal with', '處理；應對', 'to take action to handle a situation or problem', '[{"en":"How do you deal with difficult customers?","zh-TW":"你如何應對難纏的客戶？"},{"en":"We need to deal with this issue immediately.","zh-TW":"我們需要立即處理這個問題。"},{"note":"同義詞：handle, address, tackle。"}]', 'phrasal verb'),
('do away with', '廢除；去掉', 'to eliminate or get rid of something', '[{"en":"The company did away with the old filing system.","zh-TW":"公司廢除了舊的歸檔系統。"},{"en":"They plan to do away with unnecessary regulations.","zh-TW":"他們計劃廢除不必要的規定。"},{"note":"較正式，常見於政策或制度變更。"}]', 'phrasal verb'),
('draw up', '草擬；制定', 'to prepare a document, plan, or agreement', '[{"en":"The lawyer drew up the contract.","zh-TW":"律師草擬了合約。"},{"en":"We need to draw up a business plan.","zh-TW":"我們需要制定一份商業計畫。"},{"note":"同義詞：draft, prepare, formulate。"}]', 'phrasal verb'),
('drop off', '放下（人或物）；下降', 'to deliver or leave something/someone at a place', '[{"en":"I''ll drop off the documents at your office.","zh-TW":"我會把文件送到你的辦公室。"},{"en":"Sales dropped off significantly in Q4.","zh-TW":"第四季度銷售額大幅下降。"},{"note":"也可表示「減少、下降」。"}]', 'phrasal verb'),
('end up', '最終；結果是', 'to finally be in a particular place or situation', '[{"en":"We ended up postponing the launch.","zh-TW":"我們最終推遲了發佈。"},{"en":"He ended up as the CEO of the company.","zh-TW":"他最終成為了公司的CEO。"},{"note":"常用於描述意外的結果。"}]', 'phrasal verb'),
('fall behind', '落後；拖延', 'to fail to keep up with a schedule or standard', '[{"en":"The project has fallen behind schedule.","zh-TW":"這個專案已經落後於進度了。"},{"en":"Don''t fall behind on your payments.","zh-TW":"不要拖欠付款。"},{"note":"反義詞：keep up with, stay ahead of。"}]', 'phrasal verb'),
('figure out', '弄清楚；想出', 'to understand or solve something', '[{"en":"We need to figure out why sales declined.","zh-TW":"我們需要弄清楚為什麼銷售額下降了。"},{"en":"Can you figure out how to fix this?","zh-TW":"你能想出如何修復這個問題嗎？"},{"note":"同義詞：work out, solve, determine。"}]', 'phrasal verb'),
('fill in', '填寫；代替', 'to complete a form or substitute for someone', '[{"en":"Please fill in this application form.","zh-TW":"請填寫這份申請表。"},{"en":"Can you fill in for me at the meeting?","zh-TW":"你能代替我出席會議嗎？"},{"note":"fill in 側重填入資訊，fill out 側重完成整份表格。"}]', 'phrasal verb'),
('fill out', '填寫（完整表格）', 'to complete a form or document entirely', '[{"en":"All applicants must fill out the online form.","zh-TW":"所有申請人必須填寫線上表格。"},{"en":"Please fill out the survey before leaving.","zh-TW":"請在離開前填寫問卷。"},{"note":"美式英語較常用 fill out，英式用 fill in。"}]', 'phrasal verb'),
('find out', '發現；查明', 'to discover or learn information', '[{"en":"I just found out about the policy change.","zh-TW":"我剛得知政策變更的事。"},{"en":"We need to find out what went wrong.","zh-TW":"我們需要查明出了什麼問題。"},{"note":"同義詞：discover, learn, determine。"}]', 'phrasal verb'),
('follow up', '跟進；後續追蹤', 'to take further action after an initial step', '[{"en":"I''ll follow up with the client next week.","zh-TW":"我下週會跟進客戶。"},{"en":"Don''t forget to follow up on the proposal.","zh-TW":"別忘了追蹤那份提案。"},{"note":"名詞 follow-up 表示後續行動或追蹤。"}]', 'phrasal verb'),
('get along with', '與…相處融洽', 'to have a good relationship with someone', '[{"en":"She gets along well with all her colleagues.","zh-TW":"她和所有同事都相處得很好。"},{"en":"It''s important to get along with your team.","zh-TW":"和團隊相處融洽很重要。"},{"note":"同義詞：get on with（英式）。"}]', 'phrasal verb'),
('get back to', '回覆；稍後聯繫', 'to contact someone later with information', '[{"en":"Let me get back to you on that.","zh-TW":"讓我稍後回覆你這件事。"},{"en":"I''ll get back to you with the details.","zh-TW":"我會把細節回覆給你。"},{"note":"商務場合常用的禮貌用語。"}]', 'phrasal verb'),
('get rid of', '擺脫；丟掉', 'to remove or dispose of something unwanted', '[{"en":"We need to get rid of outdated inventory.","zh-TW":"我們需要處理掉過時的庫存。"},{"en":"The company got rid of the redundant positions.","zh-TW":"公司裁撤了多餘的職位。"},{"note":"同義詞：eliminate, dispose of, discard。"}]', 'phrasal verb'),
('give up', '放棄', 'to stop trying or surrender something', '[{"en":"Don''t give up on the project yet.","zh-TW":"先別放棄這個專案。"},{"en":"He gave up his position to pursue other interests.","zh-TW":"他放棄了職位去追求其他興趣。"},{"note":"反義詞：persist, keep trying。"}]', 'phrasal verb'),
('go ahead', '進行；開始做', 'to proceed with something', '[{"en":"We decided to go ahead with the merger.","zh-TW":"我們決定繼續進行合併。"},{"en":"Go ahead and submit the report.","zh-TW":"請繼續提交報告吧。"},{"note":"常用於給予許可或鼓勵。"}]', 'phrasal verb'),
('go over', '仔細檢查；複習', 'to review or examine something carefully', '[{"en":"Let''s go over the quarterly report together.","zh-TW":"讓我們一起審閱季度報告。"},{"en":"I need to go over my notes before the presentation.","zh-TW":"我需要在簡報前複習我的筆記。"},{"note":"同義詞：review, examine, look over。"}]', 'phrasal verb'),
('go through', '經歷；仔細查閱', 'to experience or examine carefully', '[{"en":"The company is going through a restructuring.","zh-TW":"公司正在經歷重組。"},{"en":"Please go through the contract carefully.","zh-TW":"請仔細審閱合約。"},{"note":"也可表示「用完」（go through supplies）。"}]', 'phrasal verb'),
('hand in', '提交；繳交', 'to submit or give something to someone in authority', '[{"en":"Please hand in your expense reports by Friday.","zh-TW":"請在週五前提交費用報告。"},{"en":"She handed in her resignation letter.","zh-TW":"她遞交了辭職信。"},{"note":"同義詞：submit, turn in。"}]', 'phrasal verb'),
('hand out', '分發', 'to distribute something to people', '[{"en":"They handed out brochures at the trade show.","zh-TW":"他們在展覽會上分發手冊。"},{"en":"The manager handed out the new guidelines.","zh-TW":"經理分發了新的指導方針。"},{"note":"名詞 handout 指講義或分發材料。"}]', 'phrasal verb'),
('hold on', '等一下；堅持', 'to wait or continue despite difficulty', '[{"en":"Hold on, I''ll transfer you to the right department.","zh-TW":"請稍等，我會把你轉到正確的部門。"},{"en":"Hold on to those documents; we''ll need them later.","zh-TW":"保留那些文件，我們之後會用到。"},{"note":"電話用語中常見。"}]', 'phrasal verb'),
('keep up with', '跟上；保持同步', 'to stay at the same level or pace', '[{"en":"It''s hard to keep up with the latest technology.","zh-TW":"很難跟上最新的技術。"},{"en":"Production can''t keep up with demand.","zh-TW":"生產跟不上需求。"},{"note":"反義詞：fall behind。"}]', 'phrasal verb'),
('lay off', '裁員；解僱', 'to dismiss workers because of lack of work', '[{"en":"The factory laid off 200 workers.","zh-TW":"工廠裁減了200名工人。"},{"en":"Several departments are facing layoffs.","zh-TW":"好幾個部門面臨裁員。"},{"note":"名詞 layoff 指裁員行為。與 fire（因表現不佳解僱）不同。"}]', 'phrasal verb'),
('leave out', '遺漏；省略', 'to not include or omit something', '[{"en":"Don''t leave out any important details.","zh-TW":"不要遺漏任何重要細節。"},{"en":"Some key data was left out of the report.","zh-TW":"報告中遺漏了一些關鍵數據。"},{"note":"同義詞：omit, exclude。"}]', 'phrasal verb'),
('let down', '使失望', 'to disappoint someone', '[{"en":"We can''t let our clients down.","zh-TW":"我們不能讓客戶失望。"},{"en":"The supplier really let us down this time.","zh-TW":"供應商這次真的讓我們失望了。"},{"note":"名詞 letdown 指令人失望的事。"}]', 'phrasal verb'),
('line up', '安排；排隊', 'to arrange or organize in order', '[{"en":"We''ve lined up three candidates for interviews.","zh-TW":"我們已安排了三位候選人面試。"},{"en":"Several investors are lined up for the project.","zh-TW":"已有幾位投資者對這個專案有興趣。"},{"note":"也指「排隊」（line up at the counter）。"}]', 'phrasal verb'),
('look after', '照顧；負責', 'to take care of someone or something', '[{"en":"Who will look after the department while you''re away?","zh-TW":"你不在的時候誰負責部門？"},{"en":"She looks after all the VIP accounts.","zh-TW":"她負責所有VIP帳戶。"},{"note":"同義詞：take care of。"}]', 'phrasal verb'),
('look forward to', '期待', 'to feel excited about something that will happen', '[{"en":"I look forward to hearing from you soon.","zh-TW":"我期待很快收到您的回覆。"},{"en":"We look forward to working with your team.","zh-TW":"我們期待與你們的團隊合作。"},{"note":"後接名詞或動名詞（V-ing）。商業書信常用。"}]', 'phrasal verb'),
('look into', '調查；研究', 'to investigate or examine something', '[{"en":"We will look into the matter immediately.","zh-TW":"我們會立即調查此事。"},{"en":"I''m looking into several options for the venue.","zh-TW":"我正在研究場地的幾個選項。"},{"note":"同義詞：investigate, examine, explore。"}]', 'phrasal verb'),
('look over', '瀏覽；檢查', 'to examine or inspect something quickly', '[{"en":"Could you look over this proposal for me?","zh-TW":"你能幫我看一下這份提案嗎？"},{"en":"I''ll look over the contract tonight.","zh-TW":"我今晚會看一下合約。"},{"note":"比 go over 更快速、不那麼仔細。"}]', 'phrasal verb'),
('look up', '查閱；好轉', 'to search for information or improve', '[{"en":"You can look up the details on our website.","zh-TW":"你可以在我們的網站上查閱詳情。"},{"en":"Business is finally looking up.","zh-TW":"生意終於好轉了。"},{"note":"look up to 表示「尊敬」。"}]', 'phrasal verb'),
('make up', '組成；編造；彌補', 'to constitute or compensate', '[{"en":"Women make up 45% of our workforce.","zh-TW":"女性佔我們勞動力的45%。"},{"en":"We need to make up for lost time.","zh-TW":"我們需要彌補失去的時間。"},{"note":"make up for 表示「彌補」。"}]', 'phrasal verb'),
('make up for', '彌補；補償', 'to compensate for something lost or missed', '[{"en":"The team worked overtime to make up for the delay.","zh-TW":"團隊加班以彌補延遲。"},{"en":"Nothing can make up for poor customer service.","zh-TW":"沒什麼能彌補糟糕的客戶服務。"},{"note":"同義詞：compensate for。"}]', 'phrasal verb'),
('move on', '繼續前進；轉向下一個', 'to proceed to the next thing', '[{"en":"Let''s move on to the next agenda item.","zh-TW":"讓我們進入下一個議程。"},{"en":"It''s time to move on from this issue.","zh-TW":"是時候放下這個問題往前走了。"},{"note":"會議中常用來轉換話題。"}]', 'phrasal verb'),
('narrow down', '縮小範圍', 'to reduce the number of options or possibilities', '[{"en":"We''ve narrowed down the candidates to three.","zh-TW":"我們已將候選人縮減到三位。"},{"en":"Let''s narrow down the options before deciding.","zh-TW":"讓我們在決定前縮小選項範圍。"},{"note":"常用於決策過程。"}]', 'phrasal verb'),
('opt for', '選擇', 'to choose one option over others', '[{"en":"Most employees opted for the flexible schedule.","zh-TW":"大多數員工選擇了彈性工時。"},{"en":"We opted for the more affordable solution.","zh-TW":"我們選擇了更經濟實惠的方案。"},{"note":"同義詞：choose, select, go for。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('pass on', '傳遞；轉交；拒絕', 'to give information to someone else or decline', '[{"en":"Could you pass on this message to the director?","zh-TW":"你能把這個訊息轉達給主管嗎？"},{"en":"I''ll have to pass on that offer.","zh-TW":"我必須拒絕那個提議。"},{"note":"pass on 也可委婉表示「拒絕」。"}]', 'phrasal verb'),
('pay off', '還清；得到回報', 'to finish paying a debt or yield good results', '[{"en":"All our hard work finally paid off.","zh-TW":"我們所有的努力終於得到了回報。"},{"en":"She paid off her student loans in five years.","zh-TW":"她在五年內還清了學生貸款。"},{"note":"作為成語意味「值得、有回報」。"}]', 'phrasal verb'),
('pick up', '拿起；學會；接載；好轉', 'to collect, learn, or improve', '[{"en":"She picked up some useful skills at the workshop.","zh-TW":"她在研討會上學到了一些有用的技能。"},{"en":"Sales usually pick up in the holiday season.","zh-TW":"銷售通常在假期旺季好轉。"},{"note":"多義詞，根據上下文判斷意思。"}]', 'phrasal verb'),
('point out', '指出', 'to draw attention to something', '[{"en":"I''d like to point out a few errors in the report.","zh-TW":"我想指出報告中的一些錯誤。"},{"en":"She pointed out the benefits of the new system.","zh-TW":"她指出了新系統的好處。"},{"note":"同義詞：highlight, indicate, note。"}]', 'phrasal verb'),
('put forward', '提出（建議或計畫）', 'to propose or suggest an idea', '[{"en":"He put forward a proposal for restructuring.","zh-TW":"他提出了一份重組提案。"},{"en":"Several ideas were put forward at the brainstorming session.","zh-TW":"腦力激盪會議上提出了幾個想法。"},{"note":"同義詞：propose, suggest, present。"}]', 'phrasal verb'),
('put off', '延期；使反感', 'to postpone or discourage someone', '[{"en":"We had to put off the product launch.","zh-TW":"我們不得不延期產品發佈。"},{"en":"Don''t be put off by the initial cost.","zh-TW":"不要被初始成本嚇退。"},{"note":"同義詞（延期）：postpone, delay, defer。"}]', 'phrasal verb'),
('put together', '組合；準備', 'to assemble or prepare something', '[{"en":"She put together a great presentation.","zh-TW":"她準備了一份很棒的簡報。"},{"en":"We need to put together a project team.","zh-TW":"我們需要組建一個專案團隊。"},{"note":"同義詞：assemble, compile, prepare。"}]', 'phrasal verb'),
('put up with', '忍受', 'to tolerate something unpleasant', '[{"en":"We can''t put up with any more delays.","zh-TW":"我們不能再忍受任何延誤了。"},{"en":"Employees shouldn''t have to put up with harassment.","zh-TW":"員工不應該忍受騷擾。"},{"note":"同義詞：tolerate, endure, bear。"}]', 'phrasal verb'),
('rely on', '依賴；信賴', 'to depend on or trust someone or something', '[{"en":"We rely heavily on our suppliers for timely delivery.","zh-TW":"我們非常依賴供應商的及時交貨。"},{"en":"You can rely on the accuracy of this data.","zh-TW":"你可以信賴這些數據的準確性。"},{"note":"同義詞：depend on, count on。"}]', 'phrasal verb'),
('run into', '偶遇；遇到（問題）', 'to meet by chance or encounter a problem', '[{"en":"We ran into some unexpected difficulties.","zh-TW":"我們遇到了一些意外的困難。"},{"en":"I ran into a former colleague at the conference.","zh-TW":"我在會議上偶遇了一位前同事。"},{"note":"同義詞：come across, encounter。"}]', 'phrasal verb'),
('run out of', '用完；耗盡', 'to have no more of something', '[{"en":"We''ve run out of printer paper.","zh-TW":"我們的印表機紙用完了。"},{"en":"Time is running out for the project deadline.","zh-TW":"專案截止日期的時間快到了。"},{"note":"也可不及物：The supplies ran out.（補給品用完了。）"}]', 'phrasal verb'),
('set up', '設立；安排；建立', 'to establish or arrange something', '[{"en":"They set up a new branch office in Taipei.","zh-TW":"他們在台北設立了一個新的分公司。"},{"en":"Can you help me set up the video conference?","zh-TW":"你能幫我設置視訊會議嗎？"},{"note":"名詞 setup 指設置或安排。"}]', 'phrasal verb'),
('show up', '出現；到場', 'to arrive or appear at a place', '[{"en":"Only half the team showed up for the meeting.","zh-TW":"只有一半的團隊成員出席了會議。"},{"en":"He didn''t show up for work today.","zh-TW":"他今天沒有來上班。"},{"note":"同義詞：appear, arrive, turn up。"}]', 'phrasal verb'),
('sign up', '報名；註冊', 'to register or enroll for something', '[{"en":"Over 100 people signed up for the seminar.","zh-TW":"超過100人報名了研討會。"},{"en":"You can sign up for the newsletter on our website.","zh-TW":"你可以在我們的網站上訂閱電子報。"},{"note":"名詞 sign-up 指報名或註冊。"}]', 'phrasal verb'),
('sort out', '解決；整理', 'to resolve a problem or organize something', '[{"en":"We need to sort out the scheduling conflict.","zh-TW":"我們需要解決排程衝突。"},{"en":"Let me sort out the paperwork first.","zh-TW":"讓我先把文件整理好。"},{"note":"同義詞：resolve, fix, organize。"}]', 'phrasal verb'),
('stand for', '代表；容忍', 'to represent or tolerate something', '[{"en":"CEO stands for Chief Executive Officer.","zh-TW":"CEO代表首席執行長。"},{"en":"We won''t stand for this kind of behavior.","zh-TW":"我們不會容忍這種行為。"},{"note":"在縮寫解釋中非常常見。"}]', 'phrasal verb'),
('step down', '辭職；退位', 'to resign from an important position', '[{"en":"The chairman stepped down due to health reasons.","zh-TW":"主席因健康原因辭職了。"},{"en":"She decided to step down as project lead.","zh-TW":"她決定辭去專案負責人一職。"},{"note":"同義詞：resign, retire, quit。"}]', 'phrasal verb'),
('switch off', '關閉；關掉', 'to turn off a device or stop paying attention', '[{"en":"Please switch off your mobile phones during the meeting.","zh-TW":"會議期間請關閉手機。"},{"en":"Remember to switch off the lights when you leave.","zh-TW":"離開時記得關燈。"},{"note":"同義詞：turn off。反義詞：switch on, turn on。"}]', 'phrasal verb'),
('take advantage of', '利用', 'to use an opportunity or situation to benefit', '[{"en":"You should take advantage of the training program.","zh-TW":"你應該利用這個培訓計畫。"},{"en":"Let''s take advantage of the current market conditions.","zh-TW":"讓我們利用當前的市場條件。"},{"note":"中性用法指善用機會，也可暗示不當利用。"}]', 'phrasal verb'),
('take into account', '考慮；納入考量', 'to consider something when making a decision', '[{"en":"We need to take all factors into account.","zh-TW":"我們需要考慮所有因素。"},{"en":"The budget takes inflation into account.","zh-TW":"預算已考慮了通貨膨脹。"},{"note":"同義詞：consider, factor in, take into consideration。"}]', 'phrasal verb'),
('take off', '起飛；脫下；開始成功', 'to leave the ground or become successful', '[{"en":"The startup really took off after the investment.","zh-TW":"新創公司在獲得投資後真正起飛了。"},{"en":"The flight takes off at 8 AM.","zh-TW":"航班早上8點起飛。"},{"note":"商務中常指事業或產品「起飛、成功」。"}]', 'phrasal verb'),
('take on', '承擔；僱用', 'to accept responsibility or hire someone', '[{"en":"She took on additional responsibilities.","zh-TW":"她承擔了額外的職責。"},{"en":"The company is taking on new staff.","zh-TW":"公司正在招聘新員工。"},{"note":"同義詞（承擔）：assume, undertake。"}]', 'phrasal verb'),
('take over', '接管；接手', 'to assume control of something', '[{"en":"A larger firm took over the company.","zh-TW":"一家較大的公司收購了該公司。"},{"en":"Who will take over when the manager retires?","zh-TW":"經理退休後誰來接手？"},{"note":"名詞 takeover 指收購或接管。"}]', 'phrasal verb'),
('take part in', '參加；參與', 'to participate in an activity or event', '[{"en":"All employees are encouraged to take part in the training.","zh-TW":"鼓勵所有員工參加培訓。"},{"en":"Over 500 companies took part in the trade fair.","zh-TW":"超過500家公司參加了貿易展覽會。"},{"note":"同義詞：participate in, join, engage in。"}]', 'phrasal verb'),
('take place', '發生；舉行', 'to happen or occur', '[{"en":"The annual meeting will take place on March 15.","zh-TW":"年度會議將於3月15日舉行。"},{"en":"Major changes have taken place in the industry.","zh-TW":"該行業發生了重大變化。"},{"note":"同義詞：occur, happen, be held。"}]', 'phrasal verb'),
('take up', '佔據；開始從事', 'to fill time/space or begin a new activity', '[{"en":"The new equipment takes up a lot of space.","zh-TW":"新設備佔了很多空間。"},{"en":"She took up the position of marketing director.","zh-TW":"她就任了行銷總監的職位。"},{"note":"take up on 表示「接受（提議）」。"}]', 'phrasal verb'),
('think over', '仔細考慮', 'to consider something carefully before deciding', '[{"en":"I need a few days to think over your offer.","zh-TW":"我需要幾天時間考慮你的提議。"},{"en":"Think it over and let me know by Monday.","zh-TW":"好好想想，週一前告訴我。"},{"note":"同義詞：consider, contemplate, deliberate。"}]', 'phrasal verb'),
('throw away', '丟掉；浪費', 'to discard or waste something', '[{"en":"Don''t throw away those receipts; we need them for tax purposes.","zh-TW":"別丟掉那些收據，我們報稅需要用。"},{"en":"We can''t throw away this opportunity.","zh-TW":"我們不能浪費這個機會。"},{"note":"同義詞：discard, dispose of, waste。"}]', 'phrasal verb'),
('try on', '試穿', 'to put on clothing to see if it fits', '[{"en":"You can try on the uniform in the fitting room.","zh-TW":"你可以在試衣間試穿制服。"},{"en":"She tried on several outfits before the interview.","zh-TW":"面試前她試穿了幾套服裝。"},{"note":"常見於購物情境。"}]', 'phrasal verb'),
('turn down', '拒絕；調低', 'to reject an offer or reduce volume/level', '[{"en":"They turned down our proposal.","zh-TW":"他們拒絕了我們的提案。"},{"en":"The bank turned down his loan application.","zh-TW":"銀行拒絕了他的貸款申請。"},{"note":"同義詞（拒絕）：reject, decline, refuse。"}]', 'phrasal verb'),
('turn in', '繳交；上交', 'to submit or hand over something', '[{"en":"All reports must be turned in by the end of the month.","zh-TW":"所有報告必須在月底前繳交。"},{"en":"He turned in his badge and ID card.","zh-TW":"他上交了他的證件和身分證。"},{"note":"同義詞：submit, hand in。"}]', 'phrasal verb'),
('turn off', '關閉', 'to stop a device or make someone lose interest', '[{"en":"Please turn off all electronic devices during the presentation.","zh-TW":"簡報期間請關閉所有電子裝置。"},{"en":"The long commute really turns off potential candidates.","zh-TW":"長途通勤真的讓潛在候選人失去興趣。"},{"note":"反義詞：turn on。"}]', 'phrasal verb'),
('turn on', '打開；開啟', 'to start a device or activate something', '[{"en":"Turn on the projector before the meeting starts.","zh-TW":"會議開始前打開投影機。"},{"en":"The heating system turns on automatically.","zh-TW":"暖氣系統會自動開啟。"},{"note":"反義詞：turn off, switch off。"}]', 'phrasal verb'),
('turn out', '結果是；證明是', 'to have a particular result', '[{"en":"The event turned out to be a great success.","zh-TW":"活動結果非常成功。"},{"en":"Things didn''t turn out as planned.","zh-TW":"事情沒有按計劃發展。"},{"note":"常用於描述意外或最終結果。"}]', 'phrasal verb'),
('turn up', '出現；調高', 'to appear or increase the level of something', '[{"en":"New evidence turned up during the audit.","zh-TW":"審計期間出現了新證據。"},{"en":"He turned up late for the interview.","zh-TW":"他面試遲到了。"},{"note":"同義詞（出現）：show up, appear。"}]', 'phrasal verb'),
('use up', '用完；耗盡', 'to consume all of something', '[{"en":"We''ve used up most of the budget already.","zh-TW":"我們已經用完了大部分預算。"},{"en":"The project used up all available resources.","zh-TW":"這個專案耗盡了所有可用資源。"},{"note":"同義詞：exhaust, deplete, consume。"}]', 'phrasal verb'),
('watch out', '小心；注意', 'to be careful or alert about something', '[{"en":"Watch out for hidden fees in the contract.","zh-TW":"注意合約中的隱藏費用。"},{"en":"Watch out for phishing emails.","zh-TW":"小心釣魚郵件。"},{"note":"同義詞：be careful, be cautious, beware。"}]', 'phrasal verb'),
('work on', '從事；致力於', 'to spend time and effort on something', '[{"en":"The team is working on the quarterly report.","zh-TW":"團隊正在撰寫季度報告。"},{"en":"We need to work on improving customer satisfaction.","zh-TW":"我們需要致力於提高客戶滿意度。"},{"note":"強調持續進行中的工作。"}]', 'phrasal verb'),
('work out', '解決；算出；結果良好', 'to solve or have a good result', '[{"en":"I''m sure everything will work out fine.","zh-TW":"我相信一切都會順利解決的。"},{"en":"We need to work out the logistics.","zh-TW":"我們需要把後勤細節弄清楚。"},{"note":"也可指「運動」（I work out every morning.）。"}]', 'phrasal verb'),
('wrap up', '完成；結束', 'to finish or conclude something', '[{"en":"Let''s wrap up the meeting; we''re running out of time.","zh-TW":"讓我們結束會議吧，我們時間不多了。"},{"en":"The project should be wrapped up by Friday.","zh-TW":"專案應該在週五前完成。"},{"note":"同義詞：conclude, finish, complete。"}]', 'phrasal verb'),
('at the latest', '最遲', 'no later than a specified time', '[{"en":"Please submit the report by Friday at the latest.","zh-TW":"請最遲在週五前提交報告。"},{"en":"The delivery will arrive by noon at the latest.","zh-TW":"交貨最遲在中午前到達。"},{"note":"用於設定截止日期。"}]', 'expression'),
('at short notice', '臨時通知；倉促地', 'with very little warning or preparation time', '[{"en":"She had to arrange the meeting at short notice.","zh-TW":"她不得不臨時安排會議。"},{"en":"We apologize for the change at such short notice.","zh-TW":"我們為如此倉促的變更致歉。"},{"note":"美式常用 on short notice。"}]', 'expression'),
('behind schedule', '落後於進度', 'later than planned', '[{"en":"The construction project is two weeks behind schedule.","zh-TW":"建設專案落後了兩週進度。"},{"en":"We can''t afford to fall further behind schedule.","zh-TW":"我們不能再繼續落後進度了。"},{"note":"反義詞：ahead of schedule, on schedule。"}]', 'expression'),
('bottom line', '底線；最終結果；利潤', 'the most important factor or the net profit', '[{"en":"The bottom line is we need to cut costs.","zh-TW":"最終結論是我們需要削減成本。"},{"en":"How will this affect our bottom line?","zh-TW":"這將如何影響我們的利潤？"},{"note":"原指財務報表的最後一行（淨利）。"}]', 'business idiom'),
('break even', '損益兩平', 'to have equal income and expenses, no profit or loss', '[{"en":"The company expects to break even by Q3.","zh-TW":"公司預計在第三季度達到損益兩平。"},{"en":"We need to sell 500 units to break even.","zh-TW":"我們需要賣出500個單位才能打平。"},{"note":"名詞 break-even point 指損益平衡點。"}]', 'business idiom'),
('bring to attention', '提請注意', 'to make someone aware of something', '[{"en":"I''d like to bring this issue to your attention.","zh-TW":"我想提請您注意這個問題。"},{"en":"It was brought to our attention that costs have risen.","zh-TW":"有人提醒我們注意成本上升了。"},{"note":"正式用語，常見於商務信件。"}]', 'expression'),
('by all means', '當然；請便', 'used to give permission or encourage', '[{"en":"By all means, feel free to contact me anytime.","zh-TW":"請隨時聯繫我，不用客氣。"},{"en":"By all means, take the day off if you need to.","zh-TW":"如果需要的話，請一定休假。"},{"note":"表示非常樂意同意的禮貌用語。"}]', 'expression'),
('close a deal', '成交；達成交易', 'to successfully complete a business agreement', '[{"en":"We managed to close the deal with the Japanese firm.","zh-TW":"我們成功與日本公司達成交易。"},{"en":"The sales team is close to closing the deal.","zh-TW":"銷售團隊即將達成交易。"},{"note":"同義詞：seal a deal, finalize an agreement。"}]', 'business idiom'),
('come into effect', '生效', 'to start being applied or enforced', '[{"en":"The new regulations come into effect next month.","zh-TW":"新法規下個月生效。"},{"en":"The policy came into effect on January 1st.","zh-TW":"該政策於1月1日生效。"},{"note":"同義詞：take effect, become effective。"}]', 'expression'),
('cut corners', '偷工減料；走捷徑', 'to do something in the cheapest or easiest way', '[{"en":"We can''t cut corners on product safety.","zh-TW":"我們不能在產品安全上偷工減料。"},{"en":"Cutting corners now will cost us more later.","zh-TW":"現在偷工減料以後會花更多錢。"},{"note":"通常帶有負面含義。"}]', 'business idiom');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('day off', '休假日', 'a day when you do not work', '[{"en":"I''m taking a day off next Monday.","zh-TW":"下週一我要休一天假。"},{"en":"Employees get two days off per week.","zh-TW":"員工每週有兩天休假。"},{"note":"複數形式：days off。"}]', 'expression'),
('due to', '由於；因為', 'because of; caused by', '[{"en":"The flight was delayed due to bad weather.","zh-TW":"航班因天氣不佳而延誤。"},{"en":"Due to high demand, the product is sold out.","zh-TW":"由於需求量大，產品已售罄。"},{"note":"較正式，可替換為 because of, owing to。"}]', 'prepositional phrase'),
('first and foremost', '首先；最重要的是', 'most importantly; before anything else', '[{"en":"First and foremost, we need to ensure customer safety.","zh-TW":"首先且最重要的是，我們需要確保客戶安全。"},{"en":"First and foremost, I want to thank the team.","zh-TW":"首先，我想感謝團隊。"},{"note":"用於強調最重要的事項。"}]', 'expression'),
('from scratch', '從零開始', 'from the very beginning with no prior preparation', '[{"en":"We built the software from scratch.","zh-TW":"我們從零開始開發了這款軟體。"},{"en":"After the fire, they had to start from scratch.","zh-TW":"火災後，他們不得不從頭開始。"},{"note":"強調沒有任何基礎或現有材料。"}]', 'expression'),
('get the ball rolling', '開始行動；啟動', 'to start an activity or process', '[{"en":"Let''s get the ball rolling on the new marketing campaign.","zh-TW":"讓我們開始啟動新的行銷活動。"},{"en":"Who''s going to get the ball rolling?","zh-TW":"誰來帶頭開始？"},{"note":"同義詞：kick off, initiate, start。"}]', 'business idiom'),
('go bankrupt', '破產', 'to be unable to pay debts and officially declared insolvent', '[{"en":"Several small businesses went bankrupt during the recession.","zh-TW":"經濟衰退期間有幾家小企業破產了。"},{"en":"The company filed for bankruptcy last month.","zh-TW":"該公司上個月申請破產。"},{"note":"名詞形式：bankruptcy。"}]', 'business idiom'),
('in advance', '預先；提前', 'before a particular time or event', '[{"en":"Please confirm your attendance in advance.","zh-TW":"請提前確認您的出席。"},{"en":"Tickets should be purchased well in advance.","zh-TW":"門票應該提前購買。"},{"note":"同義詞：beforehand, ahead of time。"}]', 'prepositional phrase'),
('in bulk', '大量地', 'in large quantities', '[{"en":"We get a discount when we order in bulk.","zh-TW":"大量訂購時我們可以獲得折扣。"},{"en":"Buying office supplies in bulk saves money.","zh-TW":"大量購買辦公用品可以省錢。"},{"note":"常與折扣、採購相關。"}]', 'prepositional phrase'),
('in charge of', '負責；管理', 'responsible for managing or controlling', '[{"en":"Who is in charge of the marketing department?","zh-TW":"誰負責行銷部門？"},{"en":"She is in charge of all overseas operations.","zh-TW":"她負責所有海外業務。"},{"note":"同義詞：responsible for, in control of。"}]', 'prepositional phrase'),
('in compliance with', '遵照；符合', 'in accordance with rules or regulations', '[{"en":"All products must be in compliance with safety standards.","zh-TW":"所有產品必須符合安全標準。"},{"en":"We operate in compliance with local regulations.","zh-TW":"我們的營運遵照當地法規。"},{"note":"法律和商業文件中常見。"}]', 'prepositional phrase'),
('in demand', '有需求的；搶手的', 'wanted or needed by many people', '[{"en":"Skilled IT professionals are in high demand.","zh-TW":"技術熟練的IT專業人員非常搶手。"},{"en":"The product is in great demand this season.","zh-TW":"這個產品本季非常搶手。"},{"note":"反義詞：out of demand。"}]', 'prepositional phrase'),
('in effect', '實際上；生效中', 'in operation or essentially', '[{"en":"The new policy is now in effect.","zh-TW":"新政策現已生效。"},{"en":"In effect, this means a 10% pay cut.","zh-TW":"實際上，這意味著減薪10%。"},{"note":"同義詞（生效）：in force, operative。"}]', 'prepositional phrase'),
('in lieu of', '代替；取代', 'instead of; in place of', '[{"en":"He received stock options in lieu of a bonus.","zh-TW":"他獲得了股票選擇權以代替獎金。"},{"en":"Payment in lieu of notice is acceptable.","zh-TW":"以支付代替通知期是可接受的。"},{"note":"正式用語，常見於合約和HR文件。"}]', 'prepositional phrase'),
('in light of', '鑒於；考慮到', 'because of; considering', '[{"en":"In light of recent developments, we''ll revise our strategy.","zh-TW":"鑒於近期發展，我們將修改策略。"},{"en":"In light of the feedback, we made several changes.","zh-TW":"考慮到回饋意見，我們做了幾處修改。"},{"note":"同義詞：considering, given, in view of。"}]', 'prepositional phrase'),
('in progress', '進行中', 'happening or being done now', '[{"en":"The renovation is still in progress.","zh-TW":"裝修仍在進行中。"},{"en":"Please do not disturb; meeting in progress.","zh-TW":"請勿打擾，會議進行中。"},{"note":"WIP = Work In Progress。"}]', 'prepositional phrase'),
('in response to', '回應；針對', 'as a reply or reaction to something', '[{"en":"In response to your inquiry, please find the attached document.","zh-TW":"針對您的詢問，請查看附件文件。"},{"en":"The company issued a statement in response to the criticism.","zh-TW":"公司針對批評發表了一份聲明。"},{"note":"商業信件常見開頭用語。"}]', 'prepositional phrase'),
('in stock', '有庫存', 'available for purchase or use', '[{"en":"The item is currently in stock.","zh-TW":"該商品目前有庫存。"},{"en":"We always keep essential supplies in stock.","zh-TW":"我們始終保持必需品有庫存。"},{"note":"反義詞：out of stock。"}]', 'prepositional phrase'),
('in terms of', '在…方面；就…而言', 'regarding; with respect to', '[{"en":"In terms of revenue, this was our best year.","zh-TW":"就收入而言，這是我們最好的一年。"},{"en":"What does this mean in terms of budget?","zh-TW":"就預算而言，這意味著什麼？"},{"note":"用於限定討論範圍。"}]', 'prepositional phrase'),
('in the long run', '從長遠來看', 'over a long period of time; eventually', '[{"en":"This investment will pay off in the long run.","zh-TW":"這項投資從長遠來看會有回報。"},{"en":"In the long run, quality is more important than price.","zh-TW":"從長遠來看，品質比價格更重要。"},{"note":"反義詞：in the short run/term。"}]', 'prepositional phrase'),
('in the meantime', '在此期間；與此同時', 'during the time between two events', '[{"en":"The results won''t be ready until Friday. In the meantime, let''s prepare the presentation.","zh-TW":"結果要到週五才會出來。在此期間，讓我們準備簡報。"},{"en":"In the meantime, please review the attached documents.","zh-TW":"在此期間，請審閱附件文件。"},{"note":"同義詞：meanwhile, in the interim。"}]', 'prepositional phrase'),
('keep track of', '追蹤；記錄', 'to monitor or record information over time', '[{"en":"We use software to keep track of inventory.","zh-TW":"我們使用軟體來追蹤庫存。"},{"en":"It''s important to keep track of all expenses.","zh-TW":"追蹤所有開支很重要。"},{"note":"反義詞：lose track of。"}]', 'expression'),
('line of work', '行業；工作領域', 'a type of job or profession', '[{"en":"What line of work are you in?","zh-TW":"你從事什麼行業？"},{"en":"In this line of work, networking is essential.","zh-TW":"在這個行業中，人脈至關重要。"},{"note":"同義詞：field, industry, profession。"}]', 'expression'),
('make a reservation', '預約；預訂', 'to book or reserve in advance', '[{"en":"I''d like to make a reservation for six people.","zh-TW":"我想預訂六人的位子。"},{"en":"Please make a reservation at the hotel.","zh-TW":"請在飯店預訂房間。"},{"note":"同義詞：book, reserve。"}]', 'expression'),
('make ends meet', '收支平衡；勉強維持生計', 'to have just enough money to pay for necessities', '[{"en":"Many families struggle to make ends meet.","zh-TW":"許多家庭勉強維持收支平衡。"},{"en":"With rising costs, it''s harder to make ends meet.","zh-TW":"隨著成本上升，維持生計變得更困難。"},{"note":"描述財務困難的常用成語。"}]', 'business idiom'),
('on behalf of', '代表', 'as a representative of someone', '[{"en":"I''m writing on behalf of the management team.","zh-TW":"我代表管理團隊撰寫此信。"},{"en":"She accepted the award on behalf of the company.","zh-TW":"她代表公司接受了獎項。"},{"note":"正式用語，常見於商務信件和演講。"}]', 'prepositional phrase'),
('on the same page', '意見一致；有共識', 'having the same understanding or opinion', '[{"en":"Let''s make sure we''re all on the same page.","zh-TW":"讓我們確保大家都有共識。"},{"en":"Are we on the same page about the deadline?","zh-TW":"關於截止日期我們意見一致嗎？"},{"note":"常用於團隊協作和會議中。"}]', 'business idiom'),
('on time', '準時', 'at the scheduled or expected time', '[{"en":"The shipment arrived on time.","zh-TW":"貨物準時到達。"},{"en":"It''s important to always be on time for meetings.","zh-TW":"開會準時很重要。"},{"note":"on time（準時）vs. in time（及時）。"}]', 'prepositional phrase'),
('out of order', '故障；壞了', 'not functioning properly', '[{"en":"The elevator is out of order today.","zh-TW":"電梯今天故障了。"},{"en":"Sorry, the copier is out of order.","zh-TW":"抱歉，影印機壞了。"},{"note":"也可指「不合規矩」。"}]', 'expression'),
('out of stock', '缺貨', 'not available for purchase', '[{"en":"That item is temporarily out of stock.","zh-TW":"該商品暫時缺貨。"},{"en":"Popular products often go out of stock quickly.","zh-TW":"熱門產品通常很快就會缺貨。"},{"note":"反義詞：in stock。"}]', 'expression'),
('prior to', '在…之前', 'before a particular time or event', '[{"en":"Please review the agenda prior to the meeting.","zh-TW":"請在會議前審閱議程。"},{"en":"Prior to joining this company, she worked in finance.","zh-TW":"加入這家公司之前，她在金融業工作。"},{"note":"比 before 更正式。"}]', 'prepositional phrase'),
('pros and cons', '優缺點；利弊', 'the advantages and disadvantages', '[{"en":"Let''s weigh the pros and cons before deciding.","zh-TW":"讓我們在決定前權衡利弊。"},{"en":"There are pros and cons to both options.","zh-TW":"兩個選項都有優缺點。"},{"note":"同義詞：advantages and disadvantages。"}]', 'expression'),
('red tape', '繁文縟節；官僚程序', 'excessive bureaucracy or rules that delay action', '[{"en":"There''s too much red tape involved in getting a permit.","zh-TW":"取得許可證涉及太多繁文縟節。"},{"en":"We need to cut through the red tape to speed up the process.","zh-TW":"我們需要減少官僚程序以加快流程。"},{"note":"帶有負面含義，指不必要的行政障礙。"}]', 'business idiom'),
('regardless of', '不管；無論', 'without being affected by something', '[{"en":"All employees will be treated fairly regardless of gender.","zh-TW":"所有員工無論性別都將受到公平對待。"},{"en":"We''ll proceed regardless of the weather.","zh-TW":"無論天氣如何我們都會繼續進行。"},{"note":"同義詞：irrespective of, no matter。"}]', 'prepositional phrase'),
('run a business', '經營企業', 'to manage and operate a company', '[{"en":"She has been running her own business for ten years.","zh-TW":"她已經經營自己的企業十年了。"},{"en":"Running a business requires dedication and planning.","zh-TW":"經營企業需要奉獻精神和規劃。"},{"note":"同義詞：manage a company, operate a firm。"}]', 'expression'),
('state of the art', '最先進的；最新技術的', 'using the latest and most advanced technology', '[{"en":"Our factory uses state-of-the-art equipment.","zh-TW":"我們的工廠使用最先進的設備。"},{"en":"The new office features state-of-the-art technology.","zh-TW":"新辦公室配備了最先進的技術。"},{"note":"作形容詞時加連字號：state-of-the-art。"}]', 'expression'),
('take effect', '生效', 'to start to produce results or be enforced', '[{"en":"The price increase will take effect from next month.","zh-TW":"漲價將從下個月開始生效。"},{"en":"The new law takes effect immediately.","zh-TW":"新法律立即生效。"},{"note":"同義詞：come into effect, become effective。"}]', 'expression'),
('take measures', '採取措施', 'to take action to achieve something or solve a problem', '[{"en":"The government took measures to reduce pollution.","zh-TW":"政府採取了措施來減少污染。"},{"en":"We must take immediate measures to address this issue.","zh-TW":"我們必須立即採取措施來解決這個問題。"},{"note":"同義詞：take steps, take action。"}]', 'expression'),
('think outside the box', '跳脫框架思考', 'to think creatively and unconventionally', '[{"en":"We need to think outside the box to solve this problem.","zh-TW":"我們需要跳脫框架思考來解決這個問題。"},{"en":"The company encourages employees to think outside the box.","zh-TW":"公司鼓勵員工創新思考。"},{"note":"指創意思維、不受傳統限制。"}]', 'business idiom'),
('touch base', '聯繫；碰面討論', 'to briefly make or renew contact with someone', '[{"en":"Let''s touch base next week to discuss progress.","zh-TW":"下週我們碰面討論進度。"},{"en":"I just wanted to touch base with you about the project.","zh-TW":"我只是想跟你聯繫一下關於這個專案的事。"},{"note":"常用於工作中的簡短溝通。"}]', 'business idiom'),
('up to date', '最新的；更新的', 'having the latest information or version', '[{"en":"Make sure your software is up to date.","zh-TW":"確保你的軟體是最新的。"},{"en":"I''ll keep you up to date on any changes.","zh-TW":"有任何變動我會讓你保持最新資訊。"},{"note":"作形容詞時加連字號：up-to-date。反義：out of date。"}]', 'expression'),
('with regard to', '關於；有關', 'concerning; about a particular subject', '[{"en":"With regard to your request, we''ll get back to you shortly.","zh-TW":"關於您的要求，我們會盡快回覆您。"},{"en":"With regard to the budget, we need to make some cuts.","zh-TW":"關於預算，我們需要做一些削減。"},{"note":"同義詞：regarding, concerning, with respect to。正式用語。"}]', 'prepositional phrase'),
('year-round', '全年的', 'happening or available throughout the year', '[{"en":"The resort offers year-round activities.","zh-TW":"度假村提供全年活動。"},{"en":"We provide year-round customer support.","zh-TW":"我們提供全年客戶支援。"},{"note":"也可寫作 all year round。"}]', 'expression'),
('as soon as possible', '盡快', 'at the earliest opportunity', '[{"en":"Please respond as soon as possible.","zh-TW":"請盡快回覆。"},{"en":"We need to resolve this issue as soon as possible.","zh-TW":"我們需要盡快解決這個問題。"},{"note":"縮寫 ASAP 在商務溝通中非常常見。"}]', 'expression'),
('bear in mind', '記住；牢記', 'to remember or consider something', '[{"en":"Bear in mind that the deadline is next Friday.","zh-TW":"請記住截止日期是下週五。"},{"en":"We should bear in mind the budget constraints.","zh-TW":"我們應該牢記預算限制。"},{"note":"同義詞：keep in mind, remember。"}]', 'expression'),
('branch out', '擴展業務；涉足新領域', 'to expand into new areas or activities', '[{"en":"The company plans to branch out into Asia.","zh-TW":"公司計劃將業務擴展到亞洲。"},{"en":"We''re branching out into renewable energy.","zh-TW":"我們正在涉足再生能源領域。"},{"note":"同義詞：diversify, expand。"}]', 'phrasal verb'),
('brush up on', '複習；溫習', 'to review or improve a skill that has been neglected', '[{"en":"I need to brush up on my Excel skills.","zh-TW":"我需要溫習一下Excel技能。"},{"en":"She brushed up on her French before the business trip.","zh-TW":"出差前她溫習了法語。"},{"note":"常用於重新學習生疏的技能。"}]', 'phrasal verb'),
('burn out', '精疲力竭；過勞', 'to become exhausted from overwork', '[{"en":"Many employees burn out from excessive overtime.","zh-TW":"許多員工因過度加班而精疲力竭。"},{"en":"We need to prevent team burnout.","zh-TW":"我們需要防止團隊過勞。"},{"note":"名詞 burnout 指職業倦怠。"}]', 'phrasal verb'),
('carry on', '繼續進行', 'to continue doing something', '[{"en":"Let''s carry on with the discussion.","zh-TW":"讓我們繼續討論。"},{"en":"Please carry on while I take this call.","zh-TW":"我接這個電話時請繼續。"},{"note":"同義詞：continue, proceed, go on。"}]', 'phrasal verb'),
('come to terms with', '接受；妥協', 'to accept a difficult situation', '[{"en":"The company had to come to terms with declining sales.","zh-TW":"公司不得不接受銷售額下降的現實。"},{"en":"We need to come to terms with the new regulations.","zh-TW":"我們需要接受新的法規。"},{"note":"也可指「達成協議」。"}]', 'expression'),
('comply with', '遵守；符合', 'to act in accordance with rules or requests', '[{"en":"All vendors must comply with our safety standards.","zh-TW":"所有供應商必須遵守我們的安全標準。"},{"en":"Failure to comply with regulations will result in fines.","zh-TW":"不遵守法規將導致罰款。"},{"note":"名詞：compliance。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('consist of', '由…組成', 'to be made up of particular parts', '[{"en":"The committee consists of ten members.","zh-TW":"委員會由十名成員組成。"},{"en":"The training program consists of three modules.","zh-TW":"培訓計劃由三個模組組成。"},{"note":"不用被動語態，不說 is consisted of。"}]', 'phrasal verb'),
('cope with', '應對；處理', 'to deal with a difficult situation successfully', '[{"en":"How do you cope with work-related stress?","zh-TW":"你如何應對工作壓力？"},{"en":"The system can''t cope with the increased demand.","zh-TW":"系統無法應對增加的需求。"},{"note":"同義詞：deal with, handle, manage。"}]', 'phrasal verb'),
('for the time being', '暫時；目前', 'for now; temporarily', '[{"en":"For the time being, we''ll keep the current system.","zh-TW":"暫時，我們會維持現有系統。"},{"en":"Let''s leave this for the time being.","zh-TW":"我們暫時先放下這個。"},{"note":"同義詞：for now, temporarily, in the meantime。"}]', 'expression'),
('gain ground', '取得進展；擴大優勢', 'to become more popular or successful', '[{"en":"Our product is gaining ground in the Asian market.","zh-TW":"我們的產品在亞洲市場取得進展。"},{"en":"The startup is gaining ground on established competitors.","zh-TW":"這家新創正在縮小與老牌競爭對手的差距。"},{"note":"反義詞：lose ground。"}]', 'business idiom'),
('get down to', '開始認真做', 'to start to give serious attention to something', '[{"en":"Let''s get down to business.","zh-TW":"讓我們言歸正傳。"},{"en":"We need to get down to the details of the contract.","zh-TW":"我們需要開始認真討論合約細節。"},{"note":"get down to business 是非常常見的商務用語。"}]', 'phrasal verb'),
('give notice', '發出通知；提出辭職', 'to formally inform of departure or action', '[{"en":"He gave two weeks'' notice before leaving.","zh-TW":"他在離職前兩週提出了辭呈。"},{"en":"Please give us advance notice of any changes.","zh-TW":"請提前通知我們任何變更。"},{"note":"resignation notice 指辭職通知。"}]', 'expression'),
('go into detail', '詳細說明', 'to explain something thoroughly', '[{"en":"I won''t go into detail here, but the results are promising.","zh-TW":"我在這裡不詳細說明，但結果很有希望。"},{"en":"Could you go into more detail about the budget?","zh-TW":"你能更詳細地說明預算嗎？"},{"note":"同義詞：elaborate, explain in detail。"}]', 'expression'),
('hold up', '延誤；阻礙；支撐', 'to delay or remain strong', '[{"en":"The shipment was held up at customs.","zh-TW":"貨物在海關被耽擱了。"},{"en":"How are sales holding up this quarter?","zh-TW":"這季度銷售表現如何？"},{"note":"名詞 holdup 指延誤或障礙。"}]', 'phrasal verb'),
('iron out', '解決（問題）；消除（分歧）', 'to resolve problems or smooth out difficulties', '[{"en":"We still need to iron out a few details.","zh-TW":"我們還需要解決一些細節問題。"},{"en":"The two parties met to iron out their differences.","zh-TW":"雙方會面以消除分歧。"},{"note":"同義詞：resolve, work out, sort out。"}]', 'phrasal verb'),
('kick off', '開始；啟動', 'to begin or start an event or project', '[{"en":"We''ll kick off the new project next Monday.","zh-TW":"我們下週一啟動新專案。"},{"en":"The sales campaign kicks off in September.","zh-TW":"銷售活動在九月啟動。"},{"note":"名詞 kickoff 指啟動會議或開始。"}]', 'phrasal verb'),
('level off', '趨於平穩', 'to stop increasing or decreasing', '[{"en":"Sales growth has leveled off this quarter.","zh-TW":"本季度銷售增長已趨於平穩。"},{"en":"Housing prices are expected to level off.","zh-TW":"房價預計將趨於平穩。"},{"note":"常用於描述圖表趨勢。"}]', 'phrasal verb'),
('live up to', '符合；達到（期望）', 'to meet expectations or standards', '[{"en":"The product didn''t live up to customer expectations.","zh-TW":"產品未能達到客戶期望。"},{"en":"We strive to live up to our reputation for quality.","zh-TW":"我們努力達到我們的品質聲譽。"},{"note":"常用於討論品質或表現。"}]', 'phrasal verb'),
('phase out', '逐步淘汰', 'to gradually stop using or producing something', '[{"en":"The company is phasing out its older product line.","zh-TW":"公司正在逐步淘汰舊產品線。"},{"en":"Plastic bags will be phased out by next year.","zh-TW":"塑膠袋將在明年前逐步淘汰。"},{"note":"反義詞：phase in（逐步引入）。"}]', 'phrasal verb'),
('pull off', '成功完成（困難的事）', 'to succeed in doing something difficult', '[{"en":"They managed to pull off the deal despite the challenges.","zh-TW":"儘管面臨挑戰，他們還是成功達成了交易。"},{"en":"Can we pull off the launch in two weeks?","zh-TW":"我們能在兩週內成功推出嗎？"},{"note":"暗示完成的事具有挑戰性。"}]', 'phrasal verb'),
('rule out', '排除', 'to decide that something is not possible', '[{"en":"We can''t rule out the possibility of a delay.","zh-TW":"我們不能排除延遲的可能性。"},{"en":"The board ruled out the merger option.","zh-TW":"董事會排除了合併選項。"},{"note":"同義詞：exclude, eliminate, discount。"}]', 'phrasal verb'),
('scale up', '擴大規模', 'to increase the size or amount of something', '[{"en":"We need to scale up production to meet demand.","zh-TW":"我們需要擴大生產以滿足需求。"},{"en":"The startup is ready to scale up its operations.","zh-TW":"這家新創已準備好擴大營運規模。"},{"note":"反義詞：scale down。"}]', 'phrasal verb'),
('settle for', '勉強接受', 'to accept something less than what you wanted', '[{"en":"Don''t settle for second best.","zh-TW":"不要勉強接受次等品。"},{"en":"We had to settle for a later delivery date.","zh-TW":"我們不得不接受較晚的交貨日期。"},{"note":"暗示妥協或退讓。"}]', 'phrasal verb'),
('shut down', '關閉；停業', 'to close a business or stop operating', '[{"en":"The factory was shut down due to safety violations.","zh-TW":"工廠因安全違規而被關閉。"},{"en":"Several stores will shut down by year-end.","zh-TW":"幾家門市將在年底前關閉。"},{"note":"名詞 shutdown 指停工或關閉。"}]', 'phrasal verb'),
('speed up', '加速', 'to make something happen faster', '[{"en":"We need to speed up the approval process.","zh-TW":"我們需要加快審批流程。"},{"en":"New technology will speed up production.","zh-TW":"新技術將加快生產速度。"},{"note":"反義詞：slow down。"}]', 'phrasal verb'),
('stand out', '突出；脫穎而出', 'to be noticeably better or different', '[{"en":"What makes your product stand out from the competition?","zh-TW":"什麼讓你的產品從競爭中脫穎而出？"},{"en":"Her resume really stood out among the applicants.","zh-TW":"她的履歷在申請者中真的很突出。"},{"note":"常用於行銷和求職情境。"}]', 'phrasal verb'),
('stem from', '源於；起因於', 'to be caused by or originate from', '[{"en":"The delay stems from a shortage of materials.","zh-TW":"延誤源於材料短缺。"},{"en":"Most complaints stem from poor communication.","zh-TW":"大多數投訴源於溝通不良。"},{"note":"同義詞：result from, arise from, originate from。"}]', 'phrasal verb'),
('stick to', '堅持；遵守', 'to continue doing something or follow a plan', '[{"en":"We need to stick to the original budget.","zh-TW":"我們需要堅持原來的預算。"},{"en":"Let''s stick to the agenda.","zh-TW":"讓我們遵循議程。"},{"note":"同義詞：adhere to, follow, abide by。"}]', 'phrasal verb'),
('weigh up', '權衡；評估', 'to consider the advantages and disadvantages', '[{"en":"We need to weigh up the risks and benefits.","zh-TW":"我們需要權衡風險和收益。"},{"en":"Take some time to weigh up your options.","zh-TW":"花些時間權衡你的選項。"},{"note":"同義詞：evaluate, assess, consider。"}]', 'phrasal verb'),
('wind down', '逐漸結束；放鬆', 'to gradually end or relax', '[{"en":"The company is winding down its overseas operations.","zh-TW":"公司正在逐漸結束其海外業務。"},{"en":"The project will wind down by end of quarter.","zh-TW":"專案將在季末逐漸結束。"},{"note":"反義詞：ramp up。"}]', 'phrasal verb'),
('write off', '勾銷；報廢', 'to cancel a debt or accept a loss', '[{"en":"The bank wrote off $2 million in bad debt.","zh-TW":"銀行勾銷了200萬美元的壞帳。"},{"en":"We had to write off the damaged equipment.","zh-TW":"我們不得不將損壞的設備報廢。"},{"note":"名詞 write-off 指勾銷或報廢品。"}]', 'phrasal verb'),
('abide by', '遵守', 'to follow or accept a rule, decision, or agreement', '[{"en":"All parties must abide by the terms of the contract.","zh-TW":"各方必須遵守合約條款。"},{"en":"Employees are expected to abide by company policies.","zh-TW":"員工應遵守公司政策。"},{"note":"同義詞：comply with, adhere to, follow。"}]', 'phrasal verb'),
('amount to', '總計；等同於', 'to total or be equivalent to', '[{"en":"Total expenses amount to $50,000.","zh-TW":"總費用達到5萬美元。"},{"en":"His contribution didn''t amount to much.","zh-TW":"他的貢獻不算多。"},{"note":"也可表示「等同於」（amount to failure）。"}]', 'phrasal verb'),
('attend to', '處理；照料', 'to deal with or give attention to', '[{"en":"I have some urgent matters to attend to.","zh-TW":"我有一些緊急事務要處理。"},{"en":"A staff member will attend to your needs.","zh-TW":"一位工作人員會照料您的需求。"},{"note":"正式用法，同義詞：take care of, deal with。"}]', 'phrasal verb'),
('boil down to', '歸結為', 'to be summarized as the most important point', '[{"en":"It all boils down to cost.","zh-TW":"歸根結底就是成本問題。"},{"en":"The decision boils down to quality versus price.","zh-TW":"這個決定歸結為品質與價格的取捨。"},{"note":"用於總結核心問題。"}]', 'phrasal verb'),
('build up', '建立；逐漸增加', 'to gradually increase or develop', '[{"en":"It takes years to build up a good reputation.","zh-TW":"建立良好聲譽需要多年時間。"},{"en":"We''ve built up a loyal customer base.","zh-TW":"我們已建立了忠實的客戶群。"},{"note":"名詞 buildup 指積累或增長。"}]', 'phrasal verb'),
('call for', '要求；需要', 'to require or demand something', '[{"en":"The situation calls for immediate action.","zh-TW":"形勢需要立即採取行動。"},{"en":"This calls for a celebration!","zh-TW":"這值得慶祝一下！"},{"note":"同義詞：require, demand, necessitate。"}]', 'phrasal verb'),
('cater to', '迎合；滿足需求', 'to provide what someone needs or wants', '[{"en":"Our services cater to small and medium businesses.","zh-TW":"我們的服務面向中小企業。"},{"en":"The hotel caters to business travelers.","zh-TW":"這家飯店面向商務旅客。"},{"note":"同義詞：serve, accommodate。"}]', 'phrasal verb'),
('on account of', '因為；由於', 'because of a particular reason', '[{"en":"The event was postponed on account of rain.","zh-TW":"活動因雨延期。"},{"en":"On account of the merger, some positions will be eliminated.","zh-TW":"由於合併，一些職位將被裁撤。"},{"note":"較正式，同義詞：due to, because of。"}]', 'prepositional phrase'),
('as a result', '因此；結果', 'because of something that has happened', '[{"en":"Sales dropped 20%. As a result, layoffs were announced.","zh-TW":"銷售下降20%。因此宣佈了裁員。"},{"en":"We invested in training. As a result, productivity improved.","zh-TW":"我們投資了培訓。因此生產力提高了。"},{"note":"同義詞：consequently, therefore, hence。"}]', 'expression'),
('as of', '自…起；截至', 'starting from a particular date or time', '[{"en":"As of January 1st, the new policy will be in effect.","zh-TW":"自1月1日起，新政策將生效。"},{"en":"As of today, we have received 300 applications.","zh-TW":"截至今天，我們已收到300份申請。"},{"note":"常用於標明生效日期。"}]', 'prepositional phrase'),
('aside from', '除了…之外', 'in addition to; except for', '[{"en":"Aside from the cost, the plan is excellent.","zh-TW":"除了成本之外，這個計劃非常好。"},{"en":"Aside from English, she speaks three other languages.","zh-TW":"除了英語，她還會說另外三種語言。"},{"note":"同義詞：apart from, besides, in addition to。"}]', 'prepositional phrase'),
('provided that', '只要；假如', 'on the condition that; if', '[{"en":"We''ll approve the loan provided that you meet the requirements.","zh-TW":"只要您符合要求，我們就會批准貸款。"},{"en":"You may leave early provided that you finish your work.","zh-TW":"只要你完成工作就可以早走。"},{"note":"同義詞：as long as, on condition that。"}]', 'expression'),
('result in', '導致', 'to cause a particular outcome', '[{"en":"The merger resulted in significant cost savings.","zh-TW":"合併導致了顯著的成本節約。"},{"en":"Poor planning can result in project failure.","zh-TW":"計劃不當可能導致專案失敗。"},{"note":"同義詞：lead to, cause, bring about。result from 指「起因於」。"}]', 'phrasal verb'),
('with respect to', '關於；就…而言', 'regarding; concerning', '[{"en":"With respect to your proposal, we have a few concerns.","zh-TW":"關於您的提案，我們有一些疑慮。"},{"en":"No changes will be made with respect to pricing.","zh-TW":"定價方面不會有任何變動。"},{"note":"非常正式，同義詞：regarding, concerning, with regard to。"}]', 'prepositional phrase'),
('according to', '根據；按照', 'as stated by a source or in accordance with', '[{"en":"According to the report, profits increased by 15%.","zh-TW":"根據報告，利潤增加了15%。"},{"en":"Everything is proceeding according to plan.","zh-TW":"一切按計劃進行中。"},{"note":"後接名詞，不接 me（用 in my opinion 代替）。"}]', 'prepositional phrase'),
('ahead of', '在…之前；領先', 'before the expected time or in front of', '[{"en":"The project was completed ahead of schedule.","zh-TW":"專案提前完成了。"},{"en":"We''re ahead of our competitors in innovation.","zh-TW":"我們在創新方面領先競爭對手。"},{"note":"反義詞：behind schedule。"}]', 'prepositional phrase'),
('ramp up', '增加；加大力度', 'to increase or intensify activity', '[{"en":"We''re ramping up production for the holiday season.","zh-TW":"我們正在為假期旺季加大產量。"},{"en":"The company ramped up its marketing efforts.","zh-TW":"公司加大了行銷力度。"},{"note":"反義詞：wind down, scale down。"}]', 'phrasal verb'),
('roll out', '推出；發佈', 'to launch or introduce a new product or service', '[{"en":"The company rolled out its new mobile app last week.","zh-TW":"公司上週推出了新的手機應用程式。"},{"en":"We plan to roll out the update in phases.","zh-TW":"我們計劃分階段推出更新。"},{"note":"名詞 rollout 指產品發佈。"}]', 'phrasal verb'),
('tighten up', '加強；使更嚴格', 'to make rules or controls more strict', '[{"en":"We need to tighten up our security procedures.","zh-TW":"我們需要加強安全程序。"},{"en":"The budget has been tightened up considerably.","zh-TW":"預算已經大幅緊縮。"},{"note":"同義詞：strengthen, reinforce。"}]', 'phrasal verb'),
('on a regular basis', '定期地', 'regularly; at consistent intervals', '[{"en":"Team meetings are held on a regular basis.","zh-TW":"團隊會議定期舉行。"},{"en":"We review performance on a quarterly basis.","zh-TW":"我們每季度審查績效。"},{"note":"同義詞：regularly, periodically, routinely。"}]', 'expression'),
('take into consideration', '考慮；納入考量', 'to think carefully about something when making decisions', '[{"en":"Please take our budget constraints into consideration.","zh-TW":"請考慮我們的預算限制。"},{"en":"All feedback will be taken into consideration.","zh-TW":"所有回饋都會被納入考量。"},{"note":"同義詞：take into account, consider。"}]', 'expression'),
('at stake', '處於危險中；攸關', 'at risk; in danger of being lost', '[{"en":"Millions of dollars are at stake.","zh-TW":"數百萬美元面臨風險。"},{"en":"Our reputation is at stake.","zh-TW":"我們的聲譽攸關。"},{"note":"強調事態的嚴重性。"}]', 'expression'),
('at all costs', '不惜一切代價', 'regardless of the price or effort required', '[{"en":"We must avoid a data breach at all costs.","zh-TW":"我們必須不惜一切代價避免數據洩露。"},{"en":"Customer trust must be maintained at all costs.","zh-TW":"必須不惜一切代價維護客戶信任。"},{"note":"表示極度重視某事。"}]', 'expression'),
('for good', '永遠地', 'permanently; forever', '[{"en":"The factory closed for good last year.","zh-TW":"工廠去年永久關閉了。"},{"en":"He left the company for good.","zh-TW":"他永遠離開了公司。"},{"note":"同義詞：permanently, for ever。"}]', 'expression'),
('in person', '親自；本人', 'physically present rather than by phone or online', '[{"en":"You need to apply in person at the office.","zh-TW":"你需要親自到辦公室申請。"},{"en":"I''d prefer to discuss this in person.","zh-TW":"我比較想當面討論這件事。"},{"note":"反義詞：remotely, online, virtually。"}]', 'expression');